"""Crypto agility: a versioned, self-describing envelope. Each envelope names its AEAD and its signature
algorithms by identifier; the registry maps identifiers to code and the policy decides what is acceptable.
Swapping AES-GCM -> ChaCha20-Poly1305 or Ed25519 -> ML-DSA is a policy change, not a flag day."""
import base64
import json
import os
import random

import registry as reg

SEED = 17  # seeds the injected fault (which document the attacker forges)


class EnvelopeError(Exception):
    """Unknown format version, or a key used with an algorithm it is not bound to."""


class NoCommonAlgorithm(Exception):
    """Negotiation found no algorithm both sides support and policy allows: fail, never fall back."""


def b64e(b: bytes) -> str:
    return base64.b64encode(b).decode()


def b64d(s: str) -> bytes:
    return base64.b64decode(s)


def canon(obj) -> bytes:
    return json.dumps(obj, sort_keys=True, separators=(",", ":")).encode()  # one byte form for AAD and signatures


class Keyring:
    """Data keys by key id; every key is bound to exactly one algorithm (key + algorithm id, RFC 7696 2.1)."""

    def __init__(self):
        self.entries = {}

    def add(self, alg_id: str) -> str:
        kid = f"dk-{len(self.entries) + 1}"
        self.entries[kid] = (alg_id, reg.new_aead_key(alg_id))
        return kid

    def primary(self) -> str:
        default = reg.POLICY["aead_default"]
        return [k for k, (a, _) in self.entries.items() if a == default][-1]  # newest key for the policy default


def signed_bytes(env: dict) -> bytes:
    return canon(env["h"]) + b"." + env["ct"].encode()


def seal(ring: Keyring, kid: str, plaintext: bytes, ctx: str, signers: dict, sig_algs=None) -> dict:
    alg, key = ring.entries[kid]
    n = os.urandom(12)
    h = {"v": 2, "aead": alg, "kid": kid, "n": b64e(n), "ctx": ctx}  # algorithm identifier travels with the data
    ct = reg.aead(alg, key, for_new_data=True).encrypt(n, plaintext, canon(h))  # whole header is AAD
    env = {"h": h, "ct": b64e(ct), "sigs": []}
    for sig_alg in sig_algs or reg.signing_algorithms():  # dual-signing while the policy phase is "transition"
        env["sigs"].append({"alg": sig_alg, "sig": b64e(reg.sign(sig_alg, signers[sig_alg], signed_bytes(env)))})
    return env


def legacy_v1(ring: Keyring, kid: str, plaintext: bytes) -> dict:
    """What the old code wrote: no algorithm identifier, the format version implied AES-256-GCM."""
    n = os.urandom(12)
    return {"h": {"v": 1, "kid": kid, "n": b64e(n)}, "ct": b64e(reg.aead(reg.LEGACY_V1_AEAD, ring.entries[kid][1]).encrypt(n, plaintext, b"")), "sigs": []}


def open_(ring: Keyring, env: dict) -> bytes:
    h = env["h"]
    if h.get("v") == 1:
        alg, aad = reg.LEGACY_V1_AEAD, b""
    elif h.get("v") == 2:
        alg, aad = h["aead"], canon(h)
    else:
        raise EnvelopeError(f"unknown envelope version {h.get('v')!r}")
    key_alg, key = ring.entries[h["kid"]]
    if key_alg != alg:  # a header cannot make a key be used with a different algorithm
        raise EnvelopeError(f"key {h['kid']} is bound to {key_alg}, header says {alg}")
    return reg.aead(alg, key).decrypt(b64d(h["n"]), b64d(env["ct"]), aad)  # registry refuses disallowed algorithms


def verify(env: dict, pubkeys: dict) -> bool:
    data = signed_bytes(env)
    # BUG on purpose: any ONE valid signature is enough - the envelope, not the verifier's policy, decides what counts
    return any(reg.verify(s["alg"], pubkeys[s["alg"]], b64d(s["sig"]), data) for s in env["sigs"] if s["alg"] in pubkeys)


def negotiate(local_prefs: list, peer_offer: list) -> str:
    for alg in local_prefs:  # our preference order wins; only active algorithms qualify
        if alg in peer_offer and reg.REGISTRY.get(alg) and reg.REGISTRY[alg].status == "active":
            return alg
    raise NoCommonAlgorithm(f"no common active algorithm in {peer_offer}")


def migrate(ring: Keyring, env: dict, signers: dict) -> dict:
    """Lazy migration: re-seal only envelopes that are legacy or not on the policy default."""
    if env["h"].get("v") == 2 and env["h"]["aead"] == reg.POLICY["aead_default"]:
        return env
    return seal(ring, ring.primary(), open_(ring, env), env["h"].get("ctx", env["h"]["kid"]), signers)


def count_by_aead(store: dict) -> dict:
    algs = [e["h"].get("aead", f"v1:{reg.LEGACY_V1_AEAD}") for e in store.values()]
    return {"metric": "envelopes_by_aead", **{a: algs.count(a) for a in sorted(set(algs))}}  # observability


if __name__ == "__main__":
    rng = random.Random(SEED)
    ring = Keyring()
    ring.add(reg.POLICY["aead_default"])
    signers = {a: reg.new_signer(a) for a in reg.signing_algorithms()}
    pubs = {a: k.public_key() for a, k in signers.items()}
    store = {f"doc-{i}": seal(ring, ring.primary(), f"invoice {i}: amount={100 * i}".encode(), f"doc-{i}", signers) for i in range(1, 4)}
    e = store["doc-1"]
    print("1) sealed 3 docs | header:", {k: e["h"][k] for k in ("v", "aead", "kid")},
          "| ct bytes:", len(b64d(e["ct"])), "| sigs:", [(s["alg"], len(b64d(s["sig"]))) for s in e["sigs"]])
    reg.POLICY["aead_default"] = reg.POLICY["aead_prefs"][1]  # policy change only: new data uses the next preference
    ring.add(reg.POLICY["aead_default"])
    store["doc-4"] = seal(ring, ring.primary(), b"invoice 4: amount=400", "doc-4", signers)
    print("2) default ->", reg.POLICY["aead_default"], "| opened:", sum(1 for x in store.values() if open_(ring, x)), "of", len(store))
    print(json.dumps(count_by_aead(store)))
    prefs = reg.POLICY["aead_prefs"]
    try:
        negotiate(prefs, ["A128CBC"])  # an identifier the registry does not know
    except NoCommonAlgorithm as err:
        print("3) negotiate:", negotiate(prefs[::-1], [prefs[0], "A128CBC"]), "| only A128CBC offered ->", err)
    old = legacy_v1(ring, "dk-1", b"invoice 0: amount=0")
    new = migrate(ring, old, signers)
    print("4) legacy v1 opens:", open_(ring, old).decode(), "| migrate ->", {k: new["h"][k] for k in ("v", "aead", "kid")})
    print("--- fault: the Ed25519 key leaked; a co-tenant re-signs an edited document with Ed25519 only")
    victim = rng.choice(sorted(store))
    classic = reg.PHASES["classic"]
    forged = seal(ring, store[victim]["h"]["kid"], f"{victim}: amount={rng.randrange(1, 9)}".encode(), victim,
                  {a: signers[a] for a in classic}, sig_algs=classic)  # the ML-DSA signature is simply left out
    print("legit verify:", verify(store["doc-1"], pubs), "| forged", victim, "verify:", verify(forged, pubs),
          "| sigs on forged:", [s["alg"] for s in forged["sigs"]])

"""A PKCS#11-shaped software token: slots, PIN login, sessions, object HANDLES and attributes.
Applications get a handle and ask the token to sign; with CKA_SENSITIVE / CKA_EXTRACTABLE set right they can never
read the private key. LEARNING CODE: a software token protects nothing from a process that can read its memory -
the real boundary is SoftHSM2 / an HSM behind PKCS#11 (pkcs11_softhsm.py, pending CI)."""
import json
import random

from cryptography.hazmat.primitives import hashes, serialization as ser
from cryptography.hazmat.primitives.asymmetric import ec, ed25519

SEED = 19  # seeds the injected fault (which attribute the compromised app asks for first)
CKA_LABEL, CKA_SIGN, CKA_VALUE, CKA_CLASS = "CKA_LABEL", "CKA_SIGN", "CKA_VALUE", "CKA_CLASS"
CKA_SENSITIVE, CKA_EXTRACTABLE = "CKA_SENSITIVE", "CKA_EXTRACTABLE"
CKA_ALWAYS_SENSITIVE, CKA_NEVER_EXTRACTABLE = "CKA_ALWAYS_SENSITIVE", "CKA_NEVER_EXTRACTABLE"
CKM_EDDSA, CKM_ECDSA_SHA256 = "CKM_EDDSA", "CKM_ECDSA_SHA256"
MAX_PIN_TRIES = 3


class PKCS11Error(Exception):
    """Carries a PKCS#11 return value name, e.g. CKR_ATTRIBUTE_SENSITIVE."""


class SoftToken:
    def __init__(self, label: str, so_pin: str, user_pin: str):
        self.label, self._pins, self._tries = label, {"SO": so_pin, "USER": user_pin}, 0
        self._objects, self._next = {}, 1
        self.audit = []  # JSON events: who did what with which handle

    def open_session(self):
        return Session(self)

    def _log(self, **event):
        self.audit.append(json.dumps(event, sort_keys=True))


class Session:
    def __init__(self, token: SoftToken):
        self.t, self.user = token, None

    def login(self, user_type: str, pin: str):
        if self.t._tries >= MAX_PIN_TRIES:
            raise PKCS11Error("CKR_PIN_LOCKED")
        if pin != self.t._pins[user_type]:
            self.t._tries += 1
            self.t._log(op="C_Login", user=user_type, ok=False)
            raise PKCS11Error("CKR_PIN_INCORRECT")
        self.t._tries, self.user = 0, user_type
        self.t._log(op="C_Login", user=user_type, ok=True)

    def _new(self, attrs, key) -> int:
        h, self.t._next = self.t._next, self.t._next + 1
        self.t._objects[h] = {"attrs": attrs, "key": key}
        return h

    def generate_key_pair(self, mechanism: str, label: str, private_template=None):
        if self.user != "USER":
            raise PKCS11Error("CKR_USER_NOT_LOGGED_IN")  # the SO administers the token but cannot use keys
        key = ed25519.Ed25519PrivateKey.generate() if mechanism == CKM_EDDSA else ec.generate_private_key(ec.SECP256R1())
        # BUG on purpose: when the template omits them, defaults are "sensitive: no, extractable: yes"
        attrs = {CKA_CLASS: "CKO_PRIVATE_KEY", CKA_LABEL: label, CKA_SIGN: True, CKA_SENSITIVE: False, CKA_EXTRACTABLE: True,
                 **(private_template or {})}
        attrs[CKA_ALWAYS_SENSITIVE], attrs[CKA_NEVER_EXTRACTABLE] = attrs[CKA_SENSITIVE], not attrs[CKA_EXTRACTABLE]
        priv = self._new(attrs, key)
        pub = self._new({CKA_CLASS: "CKO_PUBLIC_KEY", CKA_LABEL: label, CKA_SENSITIVE: False}, key.public_key())
        self.t._log(op="C_GenerateKeyPair", label=label, mechanism=mechanism, handle=priv)
        return pub, priv

    def find_objects(self, label: str, cls: str = "CKO_PRIVATE_KEY") -> list:
        return [h for h, o in self.t._objects.items() if o["attrs"].get(CKA_LABEL) == label and o["attrs"][CKA_CLASS] == cls]

    def get_attribute_value(self, handle: int, attr: str):
        o = self.t._objects[handle]
        if attr == CKA_VALUE:
            if o["attrs"][CKA_CLASS] == "CKO_PUBLIC_KEY":
                return o["key"].public_bytes(ser.Encoding.DER, ser.PublicFormat.SubjectPublicKeyInfo)
            if o["attrs"][CKA_SENSITIVE] or not o["attrs"][CKA_EXTRACTABLE]:
                self.t._log(op="C_GetAttributeValue", attr=attr, handle=handle, ok=False)
                raise PKCS11Error("CKR_ATTRIBUTE_SENSITIVE")  # the key never leaves the token in plaintext
            self.t._log(op="C_GetAttributeValue", attr=attr, handle=handle, ok=True)
            return o["key"].private_bytes(ser.Encoding.DER, ser.PrivateFormat.PKCS8, ser.NoEncryption())
        return o["attrs"][attr]

    def set_attribute_value(self, handle: int, attr: str, value: bool):
        attrs = self.t._objects[handle]["attrs"]
        if (attr == CKA_SENSITIVE and attrs[attr] and not value) or (attr == CKA_EXTRACTABLE and not attrs[attr] and value):
            raise PKCS11Error("CKR_ATTRIBUTE_READ_ONLY")  # one-way switches: sensitive stays on, extractable stays off
        attrs[attr] = value
        attrs[CKA_ALWAYS_SENSITIVE] &= attrs[CKA_SENSITIVE]
        attrs[CKA_NEVER_EXTRACTABLE] &= not attrs[CKA_EXTRACTABLE]

    def wrap_key(self, wrapping_handle: int, handle: int) -> bytes:
        if not self.t._objects[handle]["attrs"][CKA_EXTRACTABLE]:
            raise PKCS11Error("CKR_KEY_UNEXTRACTABLE")
        return b"wrapped:" + self.get_attribute_value(handle, CKA_VALUE)[:8]  # placeholder: real tokens wrap with a key

    def sign(self, handle: int, mechanism: str, data: bytes) -> bytes:
        if self.user != "USER":
            raise PKCS11Error("CKR_USER_NOT_LOGGED_IN")
        o = self.t._objects[handle]
        if not o["attrs"].get(CKA_SIGN):
            raise PKCS11Error("CKR_KEY_FUNCTION_NOT_PERMITTED")
        self.t._log(op="C_Sign", handle=handle, mechanism=mechanism, bytes=len(data))
        return o["key"].sign(data) if mechanism == CKM_EDDSA else o["key"].sign(data, ec.ECDSA(hashes.SHA256()))

    def logout(self):
        self.user = None


if __name__ == "__main__":
    rng = random.Random(SEED)
    token = SoftToken("kb-l19", so_pin="so-demo-1234", user_pin="user-demo-5678")  # demo PINs only
    s = token.open_session()
    try:
        s.login("USER", "0000")
    except PKCS11Error as e:
        print("1) wrong PIN:", e)
    s.login("USER", "user-demo-5678")
    pub, priv = s.generate_key_pair(CKM_EDDSA, "release-signing")  # app relies on the token's defaults
    sig = s.sign(priv, CKM_EDDSA, b"release 1.4.0")
    print("2) signed via handle", priv, "| sig bytes:", len(sig), "| public key DER bytes:", len(s.get_attribute_value(pub, CKA_VALUE)))
    print("--- fault: a compromised app asks the token for the private key")
    ask = rng.sample([CKA_VALUE, CKA_EXTRACTABLE, CKA_SENSITIVE], 3)
    print("attributes:", {a: (len(v) if isinstance(v, bytes) else v) for a in ask for v in [s.get_attribute_value(priv, a)]})
    stolen = ser.load_der_private_key(s.get_attribute_value(priv, CKA_VALUE), None)
    s.logout()
    print("after logout the stolen key still signs offline:", stolen.sign(b"release 6.6.6") is not None,
          "| audit events:", len(token.audit))

"""Toy MLS-style group key (RFC 9420 ideas, NOT the MLS wire protocol): a ratchet tree of X25519 node keys,
epochs, and Commits that inject fresh entropy. A Commit encrypts new path secrets (HPKE) to the resolution of each
copath node - about log2(n) encryptions - so only current members can compute the next epoch secret."""
import os
import random

from cryptography.exceptions import InvalidTag
from cryptography.hazmat.primitives import hashes, hpke
from cryptography.hazmat.primitives.asymmetric import x25519
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.kdf.hkdf import HKDF

import tree_math as tm

SEED = 20  # seeds the injected fault (who is removed, who commits)
SUITE = hpke.Suite(hpke.KEM.X25519, hpke.KDF.HKDF_SHA256, hpke.AEAD.AES_128_GCM)


def kdf(secret: bytes, label: bytes) -> bytes:
    return HKDF(hashes.SHA256(), 32, salt=None, info=b"kb-l20 " + label).derive(secret)


def node_key(path_secret: bytes) -> x25519.X25519PrivateKey:
    return x25519.X25519PrivateKey.from_private_bytes(kdf(path_secret, b"node"))  # key pair derived from the path secret


class Member:
    def __init__(self, name: str):
        self.name, self.privs, self.epoch, self.epoch_secret, self.init_secret = name, {}, 0, None, None


class Group:
    def __init__(self, names: list):
        self.n = len(names)  # power of two in this toy (no tree growth)
        self.members = {name: Member(name) for name in names}
        self.index = {name: i for i, name in enumerate(names)}
        self.nodes, self.encryptions = {}, 0
        privs = {x: x25519.X25519PrivateKey.generate() for x in range(1, 2 * self.n)}  # creator builds the tree
        self.nodes = {x: k.public_key() for x, k in privs.items()}
        first, init = os.urandom(32), os.urandom(32)
        for name, m in self.members.items():  # "Welcome": each member learns keys on its own direct path only
            x = tm.leaf(self.n, self.index[name])
            m.privs = {y: privs[y] for y in [x] + tm.direct_path(x)}
            m.epoch_secret, m.init_secret = first, init

    def _remove(self, name: str):
        self.nodes[tm.leaf(self.n, self.index.pop(name))] = None
        # BUG on purpose: RFC 9420 12.1.3 also blanks the removed leaf's direct path; here those parent keys stay

    def commit(self, committer: str, remove: str = None):
        if remove:
            self._remove(remove)
        c, x = self.members[committer], tm.leaf(self.n, self.index[committer])
        ps = os.urandom(32)  # fresh entropy: the heart of post-compromise security
        c.privs[x] = node_key(ps)
        self.nodes[x] = c.privs[x].public_key()
        sent = []
        for parent, sibling in zip(tm.direct_path(x), tm.copath(x)):
            ps = kdf(ps, b"path")
            c.privs[parent] = node_key(ps)
            self.nodes[parent] = c.privs[parent].public_key()
            for target in tm.resolution(self.nodes, sibling, self.n):  # everyone under the sibling, as few keys as possible
                sent.append((parent, target, SUITE.encrypt(ps, self.nodes[target], info=b"kb-l20 path")))
                self.encryptions += 1
        receivers = [m for name, m in self.members.items() if name != committer]
        for m in receivers:  # removed members try too: they keep whatever keys they had
            self._process(m, sent, x)
        self._advance(c, kdf(ps, b"commit"))
        return len(sent)

    def _process(self, m: Member, sent: list, committer_leaf: int):
        for parent, target, ct in sent:
            if target in m.privs:
                try:
                    ps = SUITE.decrypt(ct, m.privs[target], info=b"kb-l20 path")
                except InvalidTag:  # a stale key for a node that has since been re-keyed
                    continue
                for node in tm.direct_path(committer_leaf)[tm.direct_path(committer_leaf).index(parent):]:
                    m.privs[node] = node_key(ps)
                    last, ps = ps, kdf(ps, b"path")
                return self._advance(m, kdf(last, b"commit"))

    @staticmethod
    def _advance(m: Member, commit_secret: bytes):
        m.epoch_secret = kdf(m.init_secret + commit_secret, b"epoch")  # new epoch = old init secret + fresh commit
        m.init_secret, m.epoch = kdf(m.epoch_secret, b"init"), m.epoch + 1

    def send(self, sender: str, text: str) -> dict:
        m, n = self.members[sender], os.urandom(12)
        return {"epoch": m.epoch, "n": n, "ct": AESGCM(kdf(m.epoch_secret, b"app")).encrypt(n, text.encode(), b"%d" % m.epoch)}

    def read(self, reader: str, msg: dict):
        m = self.members[reader]
        if m.epoch != msg["epoch"]:
            return None
        try:
            return AESGCM(kdf(m.epoch_secret, b"app")).decrypt(msg["n"], msg["ct"], b"%d" % m.epoch).decode()
        except Exception:
            return None


if __name__ == "__main__":
    rng = random.Random(SEED)
    names = ["alice", "bob", "carol", "dave", "erin", "frank", "grace", "heidi"]
    g = Group(names)
    print("1) group of", g.n, "| epoch", g.members["alice"].epoch, "| alice -> all:", g.read("heidi", g.send("alice", "kick-off at 10")))
    sent = g.commit("carol")  # an empty Commit = key update (post-compromise security for carol's old keys)
    print("2) carol updates her path: HPKE encryptions:", sent, "| epoch", g.members["bob"].epoch, "| all in sync:",
          len({m.epoch_secret for m in g.members.values()}) == 1)
    removed, committer = rng.choice(names[1:4]), rng.choice(names[4:])
    print(f"--- fault: {committer} removes {removed}; the removed leaf's parent keys are not blanked")
    sent = g.commit(committer, remove=removed)
    msg = g.send(committer, "new launch date: 1 March")
    readers = {name: g.read(name, msg) is not None for name in names}
    print(f"commit HPKE encryptions: {sent} | epoch {g.members[committer].epoch} | can read post-removal message:", readers)

"""Threat model as code: a data-flow diagram (elements, zones, flows), STRIDE threats, controls, and the TESTS that
prove each control. The checker answers "did we do a good enough job?" (OWASP's 4th question) with evidence."""
import ast
import json
import random
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
TOPIC = HERE.parents[2]  # the cryptography/ folder; test references are relative to it
SEED = 21  # seeds the injected model drift (which control's test disappears)
APPLIES = {"external": "SR", "process": "STRIDE", "store": "TID", "flow": "TID"}  # STRIDE-per-element table used here


def load(path=HERE / "model.json") -> dict:
    return json.loads(Path(path).read_text(encoding="utf-8"))


def candidates(model) -> list:
    """Every (element, STRIDE letter) pair the table says to consider: the brainstorming checklist."""
    return [(name, c) for name, e in model["elements"].items() for c in APPLIES[e["type"]]]


def crosses_boundary(model, flow: dict) -> bool:
    els = model["elements"]
    return els[flow["from"]]["zone"] != els[flow["to"]]["zone"]


def test_exists(ref: str) -> bool:
    """'labs/.../test_x.py::Class::method' -> does that test function exist (AST, no import)?"""
    file, cls, meth = ref.split("::")
    path = TOPIC / file
    if not path.is_file():
        return False
    for node in ast.parse(path.read_text(encoding="utf-8")).body:
        if isinstance(node, ast.ClassDef) and node.name == cls:
            return any(isinstance(f, ast.FunctionDef) and f.name == meth for f in node.body)
    return False


def check(model) -> list:
    problems = []
    for t in model["threats"]:
        el = model["elements"].get(t["element"])
        if el is None:
            problems.append(f"{t['id']}: unknown element {t['element']}")
        elif t["stride"] not in APPLIES[el["type"]]:
            problems.append(f"{t['id']}: {t['stride']} does not apply to a {el['type']}")
        if not t["controls"] and not t.get("accepted"):
            problems.append(f"{t['id']}: no control and no recorded acceptance")
        problems += [f"{t['id']}: unknown control {c}" for c in t["controls"] if c not in model["controls"]]
    # BUG on purpose: a control counts as soon as it is NAMED - nobody checks that its tests still exist, and
    # nobody checks that every element (e.g. a newly added boundary-crossing flow) has threats at all
    return problems


def verified_controls(model) -> set:
    return set(model["controls"])  # (the unfixed checker trusts every named control)


def cheapest(node: dict, verified: set):
    """Attack tree: OR = cheapest child, AND = sum of children; a leaf behind a verified control is closed (inf)."""
    if "children" not in node:
        return (float("inf"), []) if node.get("control") in verified else (node["cost"], [node["name"]])
    kids = [cheapest(c, verified) for c in node["children"]]
    if node["type"] == "OR":
        return min(kids, key=lambda k: k[0])
    return sum(k[0] for k in kids), [step for k in kids for step in k[1]]


def tree_controls(node: dict) -> set:
    return {node["control"]} if "control" in node else set().union(*(tree_controls(c) for c in node.get("children", [])))


def mermaid(model) -> str:
    lines = ["flowchart LR"]
    for zone, label in model["boundaries"].items():
        lines.append(f'  subgraph {zone}["{label}"]')
        lines += [f"    {n.replace('-', '_')}[{n}]" for n, e in model["elements"].items() if e["type"] != "flow" and e["zone"] == zone]
        lines.append("  end")
    for name, e in model["elements"].items():
        if e["type"] == "flow":
            ids = sorted(t["id"] for t in model["threats"] if t["element"] == name)
            lines.append(f"  {e['from'].replace('-', '_')} -->|{','.join(ids) or 'NO THREATS'}| {e['to'].replace('-', '_')}")
    return "\n".join(lines)


def inject_drift(model, rng) -> str:
    """Two everyday changes: a refactor deletes a test, and a new integration adds a flow nobody modelled."""
    victim = rng.choice(sorted(tree_controls(model["attack_tree"])))
    model["controls"][victim]["tests"] = [model["controls"][victim]["tests"][0].rsplit("::", 1)[0] + "::test_removed_in_refactor"]
    model["elements"]["siem"] = {"type": "external", "zone": "internet"}
    model["elements"]["app-log->siem"] = {"type": "flow", "from": "app-log", "to": "siem"}
    return victim


